/* Presentation only: food reactions, navigation and progressive calculator input. */
(()=>{'use strict';const html=document.documentElement,calm=()=>html.dataset.motion==='calm'||matchMedia('(prefers-reduced-motion: reduce)').matches;
window.GetMacrosCompanion={respond:(type,scope)=>window.GetMacrosCharacters?.respond(type,scope),enhance:scope=>window.GetMacrosCharacters?.enhance(scope)};
function init(){
 const header=document.querySelector('.site-header');if(header&&'ResizeObserver'in window)new ResizeObserver(()=>html.style.setProperty('--header-height',header.getBoundingClientRect().height+'px')).observe(header);
 const search=document.querySelector('.nav-search');search?.addEventListener('toggle',()=>{if(search.open)search.querySelector('input').focus({preventScroll:true});});document.addEventListener('click',e=>{if(search?.open&&!search.contains(e.target))search.open=false;});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&search?.open){e.preventDefault();e.stopPropagation();search.open=false;search.querySelector('summary').focus();}});const picker=document.querySelector('.appearance-picker'),motion=document.querySelector('[data-calm-motion]');if(motion){motion.checked=html.dataset.motion==='calm';motion.addEventListener('change',()=>{html.dataset.motion=motion.checked?'calm':'full';if(motion.checked)document.getAnimations().forEach(a=>a.cancel());try{localStorage.setItem('gm-motion',html.dataset.motion);}catch{}});}
 document.addEventListener('click',e=>{if(picker?.open&&!picker.contains(e.target))picker.open=false;});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&picker?.open){e.preventDefault();e.stopPropagation();picker.open=false;picker.querySelector('summary').focus();}});
 const nav=document.querySelector('.full-nav-links');if(nav){const glide=document.createElement('span');glide.className='nav-glide';glide.setAttribute('aria-hidden','true');nav.prepend(glide);const move=target=>{if(!target)return;const box=target.getBoundingClientRect(),base=nav.getBoundingClientRect();glide.style.width=box.width+'px';glide.style.transform='translate('+(box.left-base.left)+'px,'+(box.top-base.top)+'px)';glide.style.opacity='1';};nav.addEventListener('pointerover',e=>move(e.target.closest('.nav-direct,.nav-group-trigger')));nav.addEventListener('focusin',e=>move(e.target.closest('.nav-direct,.nav-group-trigger')));nav.addEventListener('pointerleave',()=>glide.style.opacity='0');nav.addEventListener('focusout',e=>{if(!nav.contains(e.relatedTarget))glide.style.opacity='0';});}
 const home=document.querySelector('#home-guide');if(home&&window.GetMacrosGuide&&window.GetMacrosMeals){const E=window.GetMacrosMeals,meals=window.GM_MEALS||[],guide=window.GetMacrosGuide.mount(home,{meals,apply(draft){const q=E.toSearch(E.normalize(draft,meals));location.href='restaurant-meal-finder.html?'+q;}});document.querySelectorAll('[data-home-quiz],[data-launch-guide]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();guide.open();}));}
 const ensemble=document.querySelector('.food-ensemble');if(ensemble){let timer=null;const observer=new IntersectionObserver(([entry])=>{if(timer)clearInterval(timer);timer=null;if(entry.isIntersecting)timer=setInterval(()=>{if(!document.hidden&&!calm())window.GetMacrosCharacters?.respond('hello',ensemble);},9500);},{threshold:.6});observer.observe(ensemble);}portionExample();calculator();
}
function revealAnchor(hash){if(!hash||hash.length<2)return;let target;try{target=document.getElementById(decodeURIComponent(hash.slice(1)));}catch{return;}if(!target)return;target.querySelector('details.guide-category,details.restaurant-menu-sheet')?.setAttribute('open','');let parent=target.closest('details');while(parent){parent.open=true;parent=parent.parentElement.closest('details');}}
addEventListener('hashchange',()=>revealAnchor(location.hash));document.addEventListener('click',e=>{const link=e.target.closest('a[href^="#"]');if(link)revealAnchor(link.hash);});revealAnchor(location.hash);
function portionExample(){const form=document.querySelector('#portion-example-form');if(!form)return;const out=form.querySelector('output');function paint(){const total=form.elements.total.valueAsNumber,portions=form.elements.portions.valueAsNumber;if(!form.checkValidity()||!Number.isFinite(total)||!Number.isFinite(portions)){out.textContent='Enter a non-negative total and a whole number of portions.';return;}out.replaceChildren();out.append((total/portions).toLocaleString('en-US',{maximumFractionDigits:1})+' kcal per portion');const note=document.createElement('small');note.textContent=total.toLocaleString('en-US')+' ÷ '+portions+' equal portions';out.append(note);}form.addEventListener('input',paint);form.addEventListener('submit',e=>e.preventDefault());paint();}
function calculator(){const form=document.querySelector('#macro-form');if(!form)return;const fields=[...form.querySelectorAll('.macro-details>.field')];if(fields.length!==6)return;fields.forEach((f,i)=>f.dataset.calcSection=String(i<4?0:i-3));let mode='guided',step=0;const panel=form.querySelector('.calculator-presentation'),toggle=panel?.querySelector('[data-calc-switch]');if(!toggle)return;
const actions=form.querySelector('.calc-guide-nav')||document.createElement('div');actions.className='calc-guide-nav';if(!actions.children.length)actions.innerHTML='<button class="quiet-button" type="button" data-calc-back>Back</button><span data-calc-progress></span><button class="btn btn-primary" type="button" data-calc-next>Continue →</button>';if(!actions.isConnected)form.querySelector('.macro-details').after(actions);
const submit=form.querySelector('[type=submit]');function paint(){form.dataset.calcMode=mode;form.dataset.calcStep=String(step);fields.forEach(f=>f.hidden=mode==='guided'&&Number(f.dataset.calcSection)!==step);actions.hidden=mode!=='guided';actions.querySelector('[data-calc-back]').hidden=step===0;actions.querySelector('[data-calc-next]').hidden=step===2;actions.querySelector('[data-calc-progress]').textContent=(step+1)+' of 3';submit.hidden=mode==='guided'&&step!==2;panel.querySelector('.calc-step-label').textContent=mode==='compact'?'Your daily estimate':['About you','Activity','Your goal'][step];toggle.textContent=mode==='guided'?'All inputs':'Step by step';toggle.setAttribute('aria-pressed',mode==='compact');}
function focusStep(){fields.find(f=>!f.hidden)?.querySelector('input:not([hidden]),select')?.focus({preventScroll:true});}
toggle.addEventListener('click',()=>{mode=mode==='guided'?'compact':'guided';step=0;paint();});actions.querySelector('[data-calc-next]').addEventListener('click',()=>{const invalid=fields.filter(f=>!f.hidden).flatMap(f=>[...f.querySelectorAll('input,select')]).find(i=>!i.disabled&&!i.checkValidity());if(invalid){invalid.reportValidity();return;}step=Math.min(2,step+1);paint();focusStep();});actions.querySelector('[data-calc-back]').addEventListener('click',()=>{step=Math.max(0,step-1);paint();focusStep();});form.addEventListener('invalid',e=>{if(mode==='guided'){const f=e.target.closest('.field');if(f){step=Number(f.dataset.calcSection);paint();}}},true);
addEventListener('getmacros:calculator-completed',()=>queueMicrotask(()=>{const results=document.querySelector('#macro-results');if(results&&!calm())results.animate([{opacity:.7,transform:'translateY(6px)'},{opacity:1,transform:'none'}],{duration:240,easing:'cubic-bezier(.2,.8,.2,1)'});window.GetMacrosCharacters?.respond('complete');}));paint();
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
